document.querySelectorAll('[data-print]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('details.answer').forEach(d=>{d.dataset.wasOpen=d.open?'yes':'no';d.open=true;});window.print();}));window.addEventListener('afterprint',()=>document.querySelectorAll('details.answer[data-was-open]').forEach(d=>{d.open=d.dataset.wasOpen==='yes';delete d.dataset.wasOpen;}));